python3 - <<'EOF'
import re,os
def slug(h):
    h=h.strip().lower()
    h=''.join(c for c in h if c.isalnum() or c in ' -_')
    return h.replace(' ','-')
files=['AGENTS.md','TODO.md','notes/cycle-protocol.md','README.md']
anchors={}
for f in files:
    anchors[f]=set()
    for L in open(f):
        if L.startswith('#'):
            anchors[f].add(slug(L.lstrip('#')))
bad=[]
for f in files:
    d=os.path.dirname(f)
    for m in re.finditer(r'\]\(([^)]*)#([a-z0-9_-]+)\)', open(f).read()):
        path,anc=m.group(1),m.group(2)
        tgt=f if path=='' else os.path.normpath(os.path.join(d,path))
        if tgt in anchors and anc not in anchors[tgt]:
            bad.append((f,path,anc))
for b in bad: print("MISSING:",b)
print("checked; broken:",len(bad))
EOF

